import {headItemModel} from './head-textures.js';
import {rotateParts} from './affine.js';
import * as THREE from './vendor/three.module.js';
import {shapeParts} from './shapes.js';
const normals={east:[1,0,0],west:[-1,0,0],up:[0,1,0],down:[0,-1,0],south:[0,0,1],north:[0,0,-1]};
function corners(s,f){const [x,y,z]=s.map(n=>n/2);return ({east:[[x,y,z],[x,y,-z],[x,-y,z],[x,-y,-z]],west:[[-x,y,-z],[-x,y,z],[-x,-y,-z],[-x,-y,z]],up:[[-x,y,-z],[x,y,-z],[-x,y,z],[x,y,z]],down:[[-x,-y,z],[x,-y,z],[-x,-y,-z],[x,-y,-z]],south:[[-x,y,z],[x,y,z],[-x,-y,z],[x,-y,z]],north:[[x,y,-z],[-x,y,-z],[x,-y,-z],[-x,-y,-z]]})[f];}
export class ModelRenderer{
 constructor(){this.geometryCaches=new WeakMap();this.boxGeometries=new Map();this.geometryRefs=new WeakMap();this.pendingTextures=new Map();this.textures=new Map();this.materials=new Map();this.models=new Map();this.animations=[];this.failures=new Set();const c=document.createElement('canvas');c.width=c.height=16;const ctx=c.getContext('2d');for(let y=0;y<16;y++)for(let x=0;x<16;x++){ctx.fillStyle=((x>>2)+(y>>2))%2?'#552b56':'#a673ac';ctx.fillRect(x,y,1,1);}this.missing=new THREE.CanvasTexture(c);this.missing.magFilter=THREE.NearestFilter;this.missing.colorSpace=THREE.SRGBColorSpace;}
 texture(data){const url=data.url;if(this.textures.has(url))return this.textures.get(url);let settle;this.pendingTextures.set(url,new Promise(resolve=>settle=resolve));const t=new THREE.TextureLoader().load(url,loaded=>{settle();const image=loaded.image,w=data.animation?.width||image.width,h=data.animation?.height||Math.min(w,image.height),cols=Math.floor(image.width/w),rows=Math.floor(image.height/h);if(rows*cols>1){loaded.repeat.set(w/image.width,h/image.height);loaded.offset.y=1-h/image.height;const sequence=data.animation?.frames||Array.from({length:cols*rows},(_,i)=>i);if(data.animation)this.animations.push({texture:loaded,sequence,frameTime:data.animation.frametime||1,cols,rows,time:0,frame:-1});}},undefined,()=>{settle();this.failures.add(url);t.image=this.missing.image;t.needsUpdate=true;});t.colorSpace=THREE.SRGBColorSpace;t.magFilter=THREE.NearestFilter;t.minFilter=THREE.NearestFilter;t.generateMipmaps=false;this.textures.set(url,t);return t;}
 async ready(){await Promise.all(this.pendingTextures.values());}
 material(face,o,ghost=false,{side=THREE.DoubleSide,shade=true,shadeDirection=null}={}){
  const name=o.block,transparent=/glass|ice|slime|water|portal/.test(name),unshaded=!shade||shadeDirection==='up',opacity=ghost?.55:name.includes('water')?.72:name.includes('ice')?.85:1,emissive=!unshaded&&/lava|fire|glowstone|sea_lantern|shroomlight/.test(name),key=JSON.stringify([face.url,face.tint,transparent,ghost,side,unshaded,opacity,emissive]);
  if(this.materials.has(key))return this.materials.get(key);
  const Material=unshaded?THREE.MeshBasicMaterial:THREE.MeshStandardMaterial;
  const mat=new Material({map:face.url?this.texture(face):this.missing,color:face.tint||'#ffffff',...(unshaded?{}:{roughness:.9,metalness:0}),side,alphaTest:transparent?.01:.1,transparent:transparent||ghost,opacity,depthWrite:!ghost});
  if(mat.emissive&&emissive){mat.emissive.set('#ffffff');mat.emissiveMap=mat.map;mat.emissiveIntensity=.3;}
  this.materials.set(key,mat);return mat;
 }
 geometry(owner,key,create){let cache=this.boxGeometries;if(owner){if(!this.geometryCaches.has(owner))this.geometryCaches.set(owner,new Map());cache=this.geometryCaches.get(owner);}let entry=cache.get(key);if(!entry){entry={...create(),refs:0,cache,key};cache.set(key,entry);}entry.refs++;return entry;}
 partMesh(p,o,ghost=false){let entry,materials;
  if(p.mesh){entry=this.geometry(p.mesh,'mesh',()=>{const geometry=new THREE.BufferGeometry();for(const [key,size]of [['position',3],['uv',2],['normal',3]])geometry.setAttribute(key,new THREE.Float32BufferAttribute(p.mesh[key],size));geometry.setIndex(p.mesh.index);return {geometry};});materials=this.material(p.texture,o,ghost);}
  else if(p.faces){entry=this.geometry(p.faces,p.s.join(',')+'|'+(p.shadeDirection||''),()=>{const position=[],uv=[],normal=[],faces=[],byMaterial=new Map();
   for(const [f,face]of Object.entries(p.faces)){if(!normals[f])continue;const key=JSON.stringify([face.url,face.tint]),offset=position.length/3,cs=corners(p.s,f),[u0,v0,u1,v1]=face.uv||[0,0,16,16],coords=[[u0,16-v0],[u1,16-v0],[u0,16-v1],[u1,16-v1]],rotation=(((face.rotation||0)/90)%4+4)%4,perimeter=[0,1,3,2],rotated=[];for(let i=0;i<4;i++)rotated[perimeter[i]]=coords[perimeter[(i+rotation)%4]];position.push(...cs.flat());for(let i=0;i<4;i++){uv.push(...rotated[i].map(v=>v/16));normal.push(...(normals[p.shadeDirection]||normals[f]));}if(!byMaterial.has(key)){byMaterial.set(key,[]);faces.push(face);}byMaterial.get(key).push(offset,offset+2,offset+1,offset+2,offset+3,offset+1);
   }
   const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(position,3));geometry.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geometry.setAttribute('normal',new THREE.Float32BufferAttribute(normal,3));const indices=[];for(const [i,group]of [...byMaterial.values()].entries()){geometry.addGroup(indices.length,group.length,i);indices.push(...group);}geometry.setIndex(indices);return {geometry,faces};
  });// Vanilla JSON defines front and back faces separately, even on zero-thickness plants.
  // Drawing those faces twice causes coplanar mirrored textures and z-fighting.
  materials=entry.faces.map(face=>this.material(face,o,ghost,{side:THREE.FrontSide,shade:p.shade,shadeDirection:p.shadeDirection}));if(materials.length===1)materials=materials[0];}
  else{entry=this.geometry(null,p.s.join(','),()=>({geometry:new THREE.BoxGeometry(...p.s)}));const key='color:'+p.color+':'+ghost;if(!this.materials.has(key))this.materials.set(key,new THREE.MeshStandardMaterial({color:p.color||'#a673ac',roughness:1,map:p.color?null:this.missing,transparent:ghost,opacity:ghost?.55:1,depthWrite:!ghost}));materials=this.materials.get(key);}
  const mesh=new THREE.Mesh(entry.geometry,materials);this.geometryRefs.set(mesh,entry);mesh.position.fromArray(p.c);mesh.quaternion.fromArray(p.q);if(p.flip)mesh.scale.fromArray(p.flip);mesh.castShadow=!ghost;mesh.receiveShadow=true;return mesh;
 }
 async parts(assets,o,properties){const key=(o.itemDisplay||'none')+'|'+assets.key+'|'+(o.type||'block')+'|'+o.block+'|'+JSON.stringify(properties||{})+'|'+JSON.stringify([o.headTexture,o.headSkin,o.headNeedsBake,o.headSecondLayer]);if(!this.models.has(key))this.models.set(key,o.type==='item'?headItemModel(assets,o):assets.block(o.block,properties));return this.models.get(key);}
 async fill(root,o,assets,properties,ghost=false){o={...o,rightRotation:o.rightRotation?.slice(),virtual:!!o.virtual};properties={...properties};const token={};root.userData.renderToken=token;this.clear(root);root.userData.modelStatus='loading';root.userData.virtual=o.virtual;root.userData.parts=[];try{let result;if(o.type==='item'&&!o.headSkin&&!o.headTexture&&o.visualParts?.length)result={parts:o.visualParts,approximate:o.modelApproximate};else result=await this.parts(assets,o,properties);if(root.userData.renderToken!==token)return;this.clear(root);for(const p of rotateParts(result.parts,o.rightRotation)){const mesh=this.partMesh(p,o,ghost||!!o.virtual);if(o.virtual){mesh.castShadow=false;root.add(mesh);const edge=new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry),(this.virtualEdgeMaterial||=new THREE.LineBasicMaterial({color:'#a9afb7',transparent:true,opacity:.65})));edge.position.copy(mesh.position);edge.quaternion.copy(mesh.quaternion);edge.scale.copy(mesh.scale);root.add(edge);}else root.add(mesh);}root.userData.parts=result.parts;root.userData.modelStatus=result.invisible?'invisible':result.approximate?'special':'ready';root.userData.modelVersion=assets.version;root.updateMatrixWorld(true);}catch(error){if(root.userData.renderToken!==token)return;this.clear(root);for(const p of shapeParts(o).length?shapeParts(o):[{c:[0,0,0],s:[1,1,1],q:[0,0,0,1]}])root.add(this.partMesh(p,o,ghost||o.virtual));root.userData.modelStatus='missing';root.userData.modelError=error.message;}return root;}
 clear(root){for(const child of [...root.children]){root.remove(child);child.traverse(m=>{if(m.isMesh){const entry=this.geometryRefs.get(m);if(entry){this.geometryRefs.delete(m);if(--entry.refs===0){entry.geometry.dispose();entry.cache.delete(entry.key);}}else m.geometry.dispose();}else if(m.isLine)m.geometry.dispose();});}}
 disposeRoot(root){root.userData.renderToken=null;this.clear(root);}
 update(seconds){for(const a of this.animations){let tick=Math.floor(seconds*20),duration=a.sequence.reduce((sum,f)=>sum+(typeof f==='number'?a.frameTime:f.time||a.frameTime),0);tick%=duration;let entry=a.sequence[0];for(const f of a.sequence){const span=typeof f==='number'?a.frameTime:f.time||a.frameTime;if(tick<span){entry=f;break;}tick-=span;}const index=typeof entry==='number'?entry:entry.index;if(index!==a.frame){a.frame=index;a.texture.offset.set(index%a.cols/a.cols,1-(Math.floor(index/a.cols)+1)/a.rows);}}}
}
